package com.agriconnect.model; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime; @Entity @Table(name="orders") public class AgriOrder { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne private AppUser buyer; @ManyToOne private Product product; private int quantity; private BigDecimal totalPrice; private String status="PLACED"; private LocalDateTime createdAt=LocalDateTime.now(); public Long getId(){return id;} public AppUser getBuyer(){return buyer;} public void setBuyer(AppUser v){buyer=v;} public Product getProduct(){return product;} public void setProduct(Product v){product=v;} public int getQuantity(){return quantity;} public void setQuantity(int v){quantity=v;} public BigDecimal getTotalPrice(){return totalPrice;} public void setTotalPrice(BigDecimal v){totalPrice=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDateTime getCreatedAt(){return createdAt;} }